`timescale 1ns/1ps
// Self-checking testbench - generated by scripts/make_experiments.py
// One clock = one model step. Writes alpha_synapse.csv in the simulator's working directory.
module tb;
    reg clk = 0, rst = 1, en = 1;
    always #5 clk = ~clk;
    integer t, f, errors = 0;
    task check(input [8*24-1:0] what, input integer got, input integer exp);
        begin
            if (exp >= 0 && got !== exp) begin errors = errors + 1; $display("  FAIL %0s: got %0d, expected %0d", what, got, exp); end
            else $display("  ok   %0s = %0d", what, got);
            $display("RESULT %0s=%0d", what, got);
        end
    endtask
    reg pre;  wire signed [31:0] s, i_syn;
    alpha_synapse dut (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .s(s), .i_syn(i_syn));
    integer pk_single = 0, pk_burst = 0;
    initial begin
        f = $fopen("alpha_synapse.csv", "w"); $fdisplay(f, "t,pre,i_syn");
        pre = 0; repeat (2) @(posedge clk); #1 rst = 0;
        for (t = 0; t < 400; t = t + 1) begin
            pre = (t == 10) || (t >= 60 && t <= 200 && (t - 60) % 4 == 0) || (t == 330);   // single spike, then a fast burst
            @(posedge clk); #1;
            if (t < 60 && i_syn > pk_single) pk_single = i_syn;
            if (t >= 60 && t < 260 && i_syn > pk_burst) pk_burst = i_syn;
            $fdisplay(f, "%0d,%0d,%0d", t, pre, i_syn);
        end
        check("peak_single_Q8", pk_single, 402);
        check("peak_burst_Q8", pk_burst, 2078);
        if (errors == 0) $display("*** PASS ***"); else $display("*** FAIL: %0d check(s) ***", errors);
        $fclose(f); $finish;
    end
endmodule
